/*
 * oceania design tokens
 *
 * Values sourced directly from the Figma design system variables.
 * Colors stored as space-separated HSL triplets so they can be consumed via
 * `hsl(var(--token))` and `hsl(var(--token) / <alpha>)` in component CSS.
 */

@layer base {
  :root {
    /* ─── Spec annotation colors ────────────────────────────────── */
    --oc-primary-50: 245 86% 98%; /* #F4F3FE */
    --oc-primary-200: 243 89% 85%; /* #B9B6FC */
    --oc-primary-500: 254 83% 55%; /* #5F2EEA */
    --oc-primary-700: 252 82% 35%; /* #3610A2 */

    /* ─── Primary 1 (royal blue) ─────────────────────────────────── */
    --oc-blue1-100: 219 100% 91%; /* #D2E1FF */
    --oc-blue1-200: 215 100% 84%; /* #ADC7FF */
    --oc-blue1-500: 235 100% 56%; /* #2131FF */
    --oc-blue1-700: 240 100% 50%; /* #0003FF */
    --oc-blue1-800: 240 100% 42%; /* #0002D8 */
    --oc-blue1-900: 239 92% 34%; /* #0708A8 */

    /* ─── Primary 2 (electric blue) ───────────────────────────────── */
    --oc-blue2-100: 230 100% 95%; /* #E7EBFF */
    --oc-blue2-200: 232 100% 83%; /* #D1D7FF */
    --oc-blue2-400: 235 100% 84%; /* #ADB6FF */
    --oc-blue2-500: 239 100% 65%; /* #4A4CFF */
    --oc-blue2-700: 244 90% 50%; /* #2014ED */
    --oc-blue2-800: 247 84% 43%; /* #1A10C7 */

    /* ─── Primary 3 (true blue) ───────────────────────────────────── */
    --oc-blue3-200: 224 100% 90%; /* #CDD8FF */
    --oc-blue3-400: 229 100% 73%; /* #7387FF */
    --oc-blue3-500: 235 100% 62%; /* #3B4CFF */
    --oc-blue3-950: 235 100% 23%; /* #000A77 */
    --oc-blue3-900: 238 97% 35%; /* #030AAF */
    --oc-blue3-active: 239 99% 42%; /* #0109D6 */

    /* ─── Text (purple-tinted neutrals) ───────────────────────────── */
    --oc-text-200: 252 19% 87%; /* #DBD8E4 — divider/disabled fill */
    --oc-text-300: 254 19% 77%; /* #C0BACF — placeholder */
    --oc-text-400: 254 19% 67%; /* #A49CBA — hint / caption */
    --oc-text-500: 254 19% 57%; /* #887EA5 — secondary body */
    --oc-text-600: 254 17% 47%; /* #6E638D — body */
    --oc-text-800: 254 17% 27%; /* #3F3951 — primary body */
    --oc-text-900: 252 18% 17%; /* #272332 — headings */

    /* ─── Status ──────────────────────────────────────────────────── */
    --oc-error-200: 0 84% 85%; /* #F8B9B9 */
    --oc-error-500: 0 72% 45%; /* #C62020 */

    /* ─── Surface ─────────────────────────────────────────────────── */
    --oc-light: 0 0% 100%; /* #FFFFFF — Pure Light */

    /* ─── Semantic aliases ────────────────────────────────────────── */
    --oc-bg: var(--oc-light);
    --oc-fg: var(--oc-text-900);
    --oc-muted: var(--oc-primary-50);
    --oc-muted-fg: var(--oc-text-600);
    --oc-border: var(--oc-text-200);
    --oc-ring: var(--oc-blue3-500);

    --oc-primary: var(--oc-blue3-500);
    --oc-primary-fg: var(--oc-light);
    --oc-primary-hover: var(--oc-blue3-900);
    --oc-primary-active: var(--oc-blue3-active);
    --oc-primary-disabled: var(--oc-blue3-200);
    --oc-primary-subtle: var(--oc-blue3-200);

    --oc-destructive: var(--oc-error-500);
    --oc-destructive-fg: var(--oc-light);
    --oc-destructive-subtle: var(--oc-error-200);

    --oc-placeholder: var(--oc-text-600);
    --oc-hint: var(--oc-text-600);
    --oc-caption: var(--oc-text-600);

    /* ─── Radii ───────────────────────────────────────────────────── */
    --oc-radius-none: 0px;
    --oc-radius-sm: 4px; /* Figma button corner radius */
    --oc-radius-md: 4px; /* default Figma button/input corner radius */
    --oc-radius-lg: 12px;
    --oc-radius-full: 9999px;

    /* ─── Typography ──────────────────────────────────────────────── */
    --oc-font-sans: "Manrope", ui-sans-serif, system-ui, -apple-system, sans-serif;
    --oc-font-mono: "JetBrains Mono", ui-monospace, monospace;

    /* ─── Spacing primitives used by inputs ───────────────────────── */
    --oc-control-h-sm: 32px;
    --oc-control-h-md: 40px;
    --oc-control-h-lg: 48px;
    --oc-control-px: 16px;

    /* ─── Button specs from Figma ───────────────────────────────── */
    --oc-button-radius: 4px;
    --oc-button-gap-sm: 10px;
    --oc-button-gap-md: 12px;
    --oc-button-gap-lg: 12px;
    --oc-button-px-sm: 20px;
    --oc-button-py-sm: 10px;
    --oc-button-px-md: 40px;
    --oc-button-py-md: 18px;
    --oc-button-px-lg: 40px;
    --oc-button-py-lg: 22px;
    --oc-button-font-sm: 14px;
    --oc-button-font-md: 16px;
    --oc-button-font-lg: 18px;
  }

  .dark {
    /* Dark surface uses the deepest blues from the brand ramp */
    --oc-bg: var(--oc-text-900);
    --oc-fg: var(--oc-light);
    --oc-muted: var(--oc-text-800);
    --oc-muted-fg: var(--oc-text-300);
    --oc-border: var(--oc-text-600);
    --oc-ring: var(--oc-blue2-400);

    --oc-primary: var(--oc-blue2-500);
    --oc-primary-fg: var(--oc-light);
    --oc-primary-hover: var(--oc-blue2-700);
    --oc-primary-active: var(--oc-blue2-800);

    --oc-error-500: 0 84% 65%;
    --oc-destructive: 0 72% 45%;

    --oc-placeholder: var(--oc-text-400);
    --oc-hint: var(--oc-text-400);
    --oc-caption: var(--oc-text-400);
  }
}
